# The previous solution didn't satisfy the autocorrelation constraints
# Let me redo the search with proper constraints

def compute_autocorrelations(seq):
    n = len(seq)
    C = []
    for k in range(1, n):
        c_k = sum(seq[i] * seq[i+k] for i in range(n-k))
        C.append(c_k)
    return C

def search_with_pruning():
    n = 17
    seq = [None] * n
    seq[1] = -1
    seq[6] = 1
    seq[9] = -1

    best_sum_sq = [float('inf')]
    best_seq = [None]

    def compute_partial_C(seq):
        """Compute partial autocorrelations given filled positions"""
        C = [0] * 16  # C_1 to C_16
        for k in range(1, 17):
            c_k = 0
            for i in range(17 - k):
                if seq[i] is not None and seq[i+k] is not None:
                    c_k += seq[i] * seq[i+k]
            C[k-1] = c_k
        return C

    def backtrack(pos):
        if pos == n:
            C = compute_partial_C(seq)
            # Check fixed autocorrelation values
            if C[6] != 3 or C[7] != -2 or C[11] != 0:
                return False
            sum_sq = sum(c**2 for c in C)
            if sum_sq <= 40:
                best_sum_sq[0] = sum_sq
                best_seq[0] = seq[:]
                return True
            return False

        if seq[pos] is not None:
            return backtrack(pos + 1)

        for val in [-1, 1]:
            seq[pos] = val

            # Quick pruning: compute partial autocorrelations
            C = compute_partial_C(seq)
            sum_sq_lower = sum(c**2 for c in C)

            if sum_sq_lower <= 40:
                if backtrack(pos + 1):
                    return True

            seq[pos] = None

        return False

    if backtrack(0):
        print(f"Found solution: {best_seq[0]}")
        C = compute_autocorrelations(best_seq[0])
        print(f"Autocorrelations: {C}")
        print(f"Sum of squares: {best_sum_sq[0]}")
        print(f"C_7={C[6]}, C_8={C[7]}, C_12={C[11]}")
    else:
        print("No solution found with pruning")

search_with_pruning()
